import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {arrivalShot,encounterShot,rememberEncounter,albumShots} from '../journey-cinema.js';import {encounterEnemies} from '../battle.js?v=5.6.0';
const m=JSON.parse(fs.readFileSync(new URL('../../cinema/journey-manifest.json',import.meta.url))),shots=m.shots;
test('twenty locally rendered clips have matching packaged files and bounded first-eight chapter scope',()=>{assert.equal(shots.length,20);assert.equal(shots.filter(s=>s.kind==='arrival').length,8);assert.equal(shots.filter(s=>s.kind==='creature').length,12);for(const s of shots){assert.ok(fs.existsSync(new URL('../../'+s.src.replace(/^\.\//,''),import.meta.url)));assert.equal(s.duration,3.5);}assert.equal(new Set(shots.map(s=>s.id)).size,20);});
test('arrival policy excludes the civilian home, optional interiors, later chapters and repeated visits',()=>{const state={chapter:1,flags:{x:1},items:{tonic:2},gold:17};const before=JSON.stringify(state);assert.equal(arrivalShot(shots,{chapter:1,key:'home'},state),null);assert.ok(arrivalShot(shots,{chapter:1,key:'security'},state));assert.equal(arrivalShot(shots,{chapter:2,interior:'garden'},state),null);assert.equal(arrivalShot(shots,{chapter:9,key:'field'},state),null);assert.equal(JSON.stringify(state),before);state.cinemaSeen=['arrival-1'];assert.equal(arrivalShot(shots,{chapter:1,key:'security'},state),null);});
test('encounter introductions follow actual enemies and teach elder geometry rather than a stale normal move',()=>{const es=encounterEnemies(14,false,4),state={chapter:14,flags:{x:1},items:{tonic:2}};const before=JSON.stringify(state),shot=encounterShot(shots,es,state);assert.ok(shot);assert.equal(shot.title,es[0].name);assert.match(shot.subtitle,es[0].moveShape==='line'?/sideways/:/circle/);assert.equal(JSON.stringify(state),before);rememberEncounter(state,es);assert.equal(encounterShot(shots,es,state),null);assert.deepEqual(state.flags,{x:1});assert.deepEqual(state.items,{tonic:2});});
test('journey album does not spoil future destinations or creatures and supports older saves',()=>{assert.deepEqual(albumShots(shots,{chapter:1}),[]);const old=albumShots(shots,{chapter:4});assert.deepEqual(old.map(s=>s.chapter),[1,2,3]);const unlocked=albumShots(shots,{chapter:1,cinemaEncounters:['moonmoth'],cinemaSeen:['arrival-1']});assert.deepEqual(new Set(unlocked.map(s=>s.id)),new Set(['arrival-1','creature-moonmoth']));});
